import React, { useState } from 'react';
import SpaceScene from './SpaceScene';
import emailjs from 'emailjs-com';
import '../styles/shared.css';

function ContactPage() {
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    message: '',
  });
  const [confirmationMessage, setConfirmationMessage] = useState('');

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      await emailjs.send(
        process.env.REACT_APP_EMAILJS_SERVICE_ID,
        process.env.REACT_APP_EMAILJS_TEMPLATE_ID,
        formData,
        process.env.REACT_APP_EMAILJS_USER_ID
      );
      setConfirmationMessage('Thank you! Your message has been sent.');
    } catch (error) {
      console.error('Error sending email:', error);
      setConfirmationMessage(
        'Oops! Something went wrong. Please try again later.'
      );
    }
  };

  return (
    <div className='contact-container d-flex justify-content-center align-items-center vh-100'>
      <SpaceScene />
      <div
        className='card shadow-lg p-4'
        style={{ maxWidth: '500px', width: '100%' }}
      >
        <div className='card-body'>
          <h2 className='card-title text-center mb-4'>Contact Me</h2>
          <form onSubmit={handleSubmit}>
            <div className='row mb-3'>
              <div className='col'>
                <label htmlFor='firstName' className='form-label'>
                  First Name
                </label>
                <input
                  type='text'
                  className='form-control'
                  id='firstName'
                  name='firstName'
                  placeholder='First name'
                  value={formData.firstName}
                  onChange={handleChange}
                  required
                />
              </div>
              <div className='col'>
                <label htmlFor='lastName' className='form-label'>
                  Last Name
                </label>
                <input
                  type='text'
                  className='form-control'
                  id='lastName'
                  name='lastName'
                  placeholder='Last name'
                  value={formData.lastName}
                  onChange={handleChange}
                  required
                />
              </div>
            </div>
            <div className='mb-3'>
              <label htmlFor='email' className='form-label'>
                Email
              </label>
              <input
                type='email'
                className='form-control'
                id='email'
                name='email'
                placeholder='you@company.com'
                value={formData.email}
                onChange={handleChange}
                required
              />
            </div>
            <div className='mb-3'>
              <label htmlFor='phone' className='form-label'>
                Phone Number
              </label>
              <input
                type='tel'
                className='form-control'
                id='phone'
                name='phone'
                placeholder='+1 (555) 000-0000'
                value={formData.phone}
                onChange={handleChange}
              />
            </div>
            <div className='mb-3'>
              <label htmlFor='message' className='form-label'>
                Message
              </label>
              <textarea
                className='form-control'
                id='message'
                name='message'
                placeholder='Leave us a message...'
                rows='4'
                value={formData.message}
                onChange={handleChange}
                required
              />
            </div>
            <button type='submit' className='btn btn-primary w-100'>
              Send Message
            </button>
          </form>
          {confirmationMessage && (
            <div className='alert alert-info text-center mt-3'>
              {confirmationMessage}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default ContactPage;
